# Cria as 6 imagens do site na pasta atual. Rode na pasta do projeto com:
#   powershell -ExecutionPolicy Bypass -File gerar-imagens.ps1
$ErrorActionPreference = "Stop"
$imagens = [ordered]@{
  'logo-header.png' = ''
  'logo.png' = ''
  'logo-email.png' = ''
  'apple-touch-icon.png' = ''
  'icon-512.png' = ''
  'favicon.png' = ''
}
foreach ($nome in $imagens.Keys) {
  $destino = Join-Path (Get-Location) $nome
  [IO.File]::WriteAllBytes($destino, [Convert]::FromBase64String($imagens[$nome]))
  "{0,-24} {1,8} bytes" -f $nome, (Get-Item $destino).Length
}
"Pronto. Pode apagar este arquivo gerar-imagens.ps1."
